proj, target, mainG, srcG, prodG = uid("proj"), uid("target"), uid("mainG"), uid("srcG"), uid("prodG")
prod = uid("product"); assRef = uid("assRef"); assBF = uid("assBF"); extRef = uid("extRef"); extBF = uid("extBF")
