o.append(f"\t\t{icoBF} /* Doddy.icon in Resources */ = {{isa = PBXBuildFile; fileRef = {icoRef} /* Doddy.icon */; }};")
o.append(f"\t\t{assBF} /* Assets.xcassets in Resources */ = {{isa = PBXBuildFile; fileRef = {assRef} /* Assets.xcassets */; }};")
o.append("/* End PBXBuildFile section */\n")
o.append("/* Begin PBXFileReference section */")
for s in srcs: o.append(f"\t\t{fr[s]} /* {s} */ = {{isa = PBXFileReference; lastKnownFileType = sourcecode.swift; path = {s}; sourceTree = \"<group>\"; }};")
o.append(f"\t\t{extRef} /* extension */ = {{isa = PBXFileReference; lastKnownFileType = folder; path = extension; sourceTree = \"<group>\"; }};")
o.append(f"\t\t{icoRef} /* Doddy.icon */ = {{isa = PBXFileReference; lastKnownFileType = folder.iconcomposer.icon; path = IconComposer/Doddy.icon; sourceTree = \"<group>\"; }};")
o.append(f"\t\t{assRef} /* Assets.xcassets */ = {{isa = PBXFileReference; lastKnownFileType = folder.assetcatalog; path = Assets.xcassets; sourceTree = \"<group>\"; }};")
o.append(f"\t\t{prod} /* Doddy.app */ = {{isa = PBXFileReference; explicitFileType = wrapper.application; includeInIndex = 0; path = Doddy.app; sourceTree = BUILT_PRODUCTS_DIR; }};")
o.append("/* End PBXFileReference section */\n")
o.append("/* Begin PBXFrameworksBuildPhase section */")
o.append(f"\t\t{frwPhase} /* Frameworks */ = {{isa = PBXFrameworksBuildPhase; buildActionMask = 2147483647; files = (); runOnlyForDeploymentPostprocessing = 0; }};")
o.append("/* End PBXFrameworksBuildPhase section */\n")
o.append("/* Begin PBXGroup section */")
o.append(f"\t\t{mainG} = {{isa = PBXGroup; children = ({srcG} /* Doddy */, {extRef} /* extension */, {assRef} /* Assets.xcassets */, {icoRef} /* Doddy.icon */, {prodG} /* Products */, ); sourceTree = \"<group>\"; }};")
o.append(f"\t\t{srcG} /* Doddy */ = {{isa = PBXGroup; children = ({', '.join(fr[s]+' /* '+s+' */' for s in srcs)}, ); path = Doddy; sourceTree = \"<group>\"; }};")
o.append(f"\t\t{prodG} /* Products */ = {{isa = PBXGroup; children = ({prod} /* Doddy.app */, ); name = Products; sourceTree = \"<group>\"; }};")
o.append("/* End PBXGroup section */\n")
o.append("/* Begin PBXNativeTarget section */")
o.append(f"\t\t{target} /* Doddy */ = {{isa = PBXNativeTarget; buildConfigurationList = {cfgTgt}; buildPhases = ({srcPhase} /* Sources */, {frwPhase} /* Frameworks */, {resPhase} /* Resources */, ); buildRules = (); dependencies = (); name = Doddy; productName = Doddy; productReference = {prod} /* Doddy.app */; productType = \"com.apple.product-type.application\"; }};")
o.append("/* End PBXNativeTarget section */\n")
o.append("/* Begin PBXProject section */")
o.append(f"\t\t{proj} /* Project object */ = {{isa = PBXProject; attributes = {{BuildIndependentTargetsInParallel = 1; LastSwiftUpdateCheck = 1500; LastUpgradeCheck = 1500; }}; buildConfigurationList = {cfgProj}; compatibilityVersion = \"Xcode 14.0\"; developmentRegion = en; hasScannedForEncodings = 0; knownRegions = (en, Base, ); mainGroup = {mainG}; productRefGroup = {prodG} /* Products */; projectDirPath = \"\"; projectRoot = \"\"; targets = ({target} /* Doddy */, ); }};")
o.append("/* End PBXProject section */\n")
o.append("/* Begin PBXResourcesBuildPhase section */")
o.append(f"\t\t{resPhase} /* Resources */ = {{isa = PBXResourcesBuildPhase; buildActionMask = 2147483647; files = ({extBF} /* extension in Resources */, {assBF} /* Assets.xcassets in Resources */, {icoBF} /* Doddy.icon in Resources */, ); runOnlyForDeploymentPostprocessing = 0; }};")
o.append("/* End PBXResourcesBuildPhase section */\n")
