o.append(f"\t\t{srcPhase} /* Sources */ = {{isa = PBXSourcesBuildPhase; buildActionMask = 2147483647; files = ({', '.join(bf[s]+' /* '+s+' in Sources */' for s in srcs)}, ); runOnlyForDeploymentPostprocessing = 0; }};")
o.append("/* End PBXSourcesBuildPhase section */\n")
common = 'ALWAYS_SEARCH_USER_PATHS = NO; CLANG_ENABLE_MODULES = YES; CLANG_ENABLE_OBJC_ARC = YES; ENABLE_USER_SCRIPT_SANDBOXING = NO; MACOSX_DEPLOYMENT_TARGET = 13.0; SDKROOT = macosx; SWIFT_VERSION = 5.0;'
o.append("/* Begin XCBuildConfiguration section */")
o.append(f"\t\t{pD} /* Debug */ = {{isa = XCBuildConfiguration; buildSettings = {{{common} DEBUG_INFORMATION_FORMAT = dwarf; ENABLE_TESTABILITY = YES; GCC_OPTIMIZATION_LEVEL = 0; ONLY_ACTIVE_ARCH = YES; SWIFT_ACTIVE_COMPILATION_CONDITIONS = DEBUG; SWIFT_OPTIMIZATION_LEVEL = \"-Onone\"; }}; name = Debug; }};")
o.append(f"\t\t{pR} /* Release */ = {{isa = XCBuildConfiguration; buildSettings = {{{common} DEBUG_INFORMATION_FORMAT = \"dwarf-with-dsym\"; SWIFT_COMPILATION_MODE = wholemodule; }}; name = Release; }};")
tg = 'ASSETCATALOG_COMPILER_APPICON_NAME = Doddy; CODE_SIGN_STYLE = Automatic; CODE_SIGN_IDENTITY = "-"; CURRENT_PROJECT_VERSION = 1; ENABLE_HARDENED_RUNTIME = NO; GENERATE_INFOPLIST_FILE = YES; INFOPLIST_KEY_CFBundleDisplayName = Doddy; INFOPLIST_KEY_LSApplicationCategoryType = "public.app-category.utilities"; LD_RUNPATH_SEARCH_PATHS = ("$(inherited)", "@executable_path/../Frameworks"); MARKETING_VERSION = 0.2.2; PRODUCT_BUNDLE_IDENTIFIER = io.github.bunduuk.doddy; PRODUCT_NAME = Doddy; SWIFT_EMIT_LOC_STRINGS = NO;'
o.append(f"\t\t{tD} /* Debug */ = {{isa = XCBuildConfiguration; buildSettings = {{{tg} }}; name = Debug; }};")
o.append(f"\t\t{tR} /* Release */ = {{isa = XCBuildConfiguration; buildSettings = {{{tg} }}; name = Release; }};")
o.append("/* End XCBuildConfiguration section */\n")
o.append("/* Begin XCConfigurationList section */")
o.append(f"\t\t{cfgProj} = {{isa = XCConfigurationList; buildConfigurations = ({pD} /* Debug */, {pR} /* Release */, ); defaultConfigurationIsVisible = 0; defaultConfigurationName = Release; }};")
o.append(f"\t\t{cfgTgt} = {{isa = XCConfigurationList; buildConfigurations = ({tD} /* Debug */, {tR} /* Release */, ); defaultConfigurationIsVisible = 0; defaultConfigurationName = Release; }};")
o.append("/* End XCConfigurationList section */")
txt = "// !$*UTF8*$!\n{\n\tarchiveVersion = 1;\n\tclasses = {\n\t};\n\tobjectVersion = 56;\n\tobjects = {\n\n" + "\n".join(o) + f"\n\t}};\n\trootObject = {proj} /* Project object */;\n}}\n"
os.makedirs("Doddy.xcodeproj", exist_ok=True)
open("Doddy.xcodeproj/project.pbxproj", "w").write(txt)
print("wrote", len(txt), "bytes;", len(srcs), "sources")
